    def rotate(self, matrix: List[List[int]]) -> None:
        """
        Do not return anything, modify matrix in-place instead.
        """
        n = len(matrix)
        for i in range(n):
            for j in range(i, n):
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

        for i in range(len(matrix)):
            for j in range(n//2):
                matrix[i][j], matrix[i][n-1-j] = matrix[i][n-1-j], matrix[i][j]

class Solution:
    def totalNQueens(self, n: int) -> int:
        self.n = n
        self.res = 0
        self.board = []
        self.backtrack(0)
        return self.res

    # because we put only 1 Queen a row, thus process by row instead of cell
    def backtrack(self, i):
        if i == self.n:
            self.res+=1
            return

        for row in range(self.n):
            if self.checkValid(i, row):
                self.board.append(row)
                self.backtrack(i+1)
                self.board.pop()


    def index2str(self, i):
        return "." * i + "Q" + "." * (self.n-1-i)

    def checkValid(self, i, pos):
        for index, row in enumerate(self.board):
            if row == pos:
                return False
            if abs(i - index) == abs(pos - row):
                return False

        return True

class Solution:
    def generateMatrix(self, n: int) -> List[List[int]]:
        rl = 0
        ru = n-1
        cl = 0
        cu = n-1

        matrix = []
        for i in range(n):   
            temp = []    
            for j in range(n):
                temp.append(0)
            matrix.append(temp)

        cnt = 1
        while cnt <= n*n:
            for i in range(cl, cu+1):
                matrix[rl][i] = cnt
                cnt += 1
            rl += 1
            if cnt > n*n:
                break
            for i in range(rl, ru+1):
                matrix[i][cu] = cnt
                cnt += 1
            cu -= 1
            if cnt > n*n:
                break
            for i in range(cu, cl-1, -1):
                matrix[ru][i] = cnt
                cnt += 1
            ru -= 1
            if cnt > n*n:
                break
            for i in range(ru, rl-1, -1):
                matrix[i][cl] = cnt
                cnt += 1
            cl += 1
        return matrix

class Solution:
    def climbStairs(self, n: int) -> int:
        self.memo = [0] * (n+1)
        self.memo[1] = 1
        self.memo[0] = 1
        return self.helper(n)

    def helper(self, n):
        if n < 2:
            return 1
        if self.memo[n] != 0:
            return self.memo[n]
        self.memo[n] = self.helper(n-1) + self.helper(n-2)
        return self.memo[n]

