class Solution:
    def detectCycle(self, head: Optional[ListNode]) -> Optional[ListNode]:
        slow = head
        fast = head
        while fast != None and fast.next != None:
            slow = slow.next
            fast = fast.next.next
            if slow == fast:
                break
        else:
            return None
        detector = head
        while slow != None:
            if detector == slow:
                break
            detector = detector.next
            slow = slow.next

        return detector

class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        stack = []
        for tok in tokens:
            if tok not in "+-*/":
                stack.append(int(tok))
            elif tok == '+':
                op2 = stack.pop()
                op1 = stack.pop()
                stack.append(op1+op2)
            elif tok == '-':
                op2 = stack.pop()
                op1 = stack.pop()
                stack.append(op1-op2)
            elif tok == '*':
                op2 = stack.pop()
                op1 = stack.pop()
                stack.append(op1*op2)
            elif tok == '/':
                op2 = stack.pop()
                op1 = stack.pop()
                stack.append(int(op1/op2))
        return int(stack[0])

