class Solution:
    def containsNearbyDuplicate(self, nums: List[int], k: int) -> bool:
        window = {}
        left = 0
        right = 0
        while right < len(nums):
            n = nums[right]
            window[n] = window.get(n, 0) + 1
            right += 1
            while right - left > k + 1:
                nl = nums[left]
                if window.get(nl, 0) > 0:
                    window[nl] = window[nl] - 1
                left += 1
            if window.get(n, 0) > 1:
                return True
        return False

