    def calculate(self, s: str) -> int:
        # index beforehand
        self.brakets = {} # (: index
        st = []
        for i in range(len(s)):
            if s[i] == "(":
                st.append(i)
            elif s[i] == ")":
                index = st.pop()
                self.brakets[index] = i

        return self.helper(s, 0, len(s)-1)

    def helper(self, s, lo, hi):
        st = []
        num = 0
        op = "+"

        i = lo
        while i <= hi:
            c = s[i]

            if c.isalnum():
                num = num * 10 + int(c)

            elif c == "(":
                # find right )
                j = self.brakets[i]
                # recursion
                num = self.helper(s, i + 1, j - 1)
                # to stride
                # don't + 1 here for the following i == hi check
                i = j

            if c in "+-*/" or i == hi:
                # for the following should compare op not c
                if op == '+':
                    # put sign earlier, instead of judge during sum
                    st.append(num)
                    num = 0
                elif op == '-':
                    # put sign earlier, instead of judge during sum
                    st.append(-num)
                    num = 0
                elif op == '*':
                    # put sign earlier, instead of judge during sum
                    opA = st.pop()
                    st.append(opA * num)
                elif op == '/':
                    # put sign earlier, instead of judge during sum
                    opA = st.pop()
                    st.append(int(opA / num)) # goes to 0, // not
                num = 0
                op = c

            i += 1

        return sum(st)

