        if self.size > 0:
            return self.arr[self.left]
        return -1

    def Rear(self) -> int:
        if self.size > 0:
            return self.arr[(self.right - 1) % self.k]
        return -1


    def isEmpty(self) -> bool:
        return self.size == 0

    def isFull(self) -> bool:
        return self.size == self.k


