            res[i] -= nle[-1] if nle else 0
            nle.append(prices[i])
        return res

# not know whether p q exists
# should put cur val check post-order

class Solution:
    def __init__(self):
        # 用于记录 p 和 q 是否存在于二叉树中
        self.foundP = False
        self.foundQ = False

    def lowestCommonAncestor(self, root: TreeNode, p: TreeNode, q: TreeNode) -> TreeNode:
        res = self.find(root, p.val, q.val)
        if not self.foundP or not self.foundQ:
            return None
        # p 和 q 都存在二叉树中，才有公共祖先
        return res

    # 在二叉树中寻找 val1 和 val2 的最近公共祖先节点
    def find(self, root, val1, val2):
        if not root:
            return None
        left = self.find(root.left, val1, val2)
        right = self.find(root.right, val1, val2)

        # 后序位置，判断当前节点是不是 LCA 节点
        if left and right:
            return root

        # 后序位置，判断当前节点是不是目标值
        if root.val == val1 or root.val == val2:
            # 找到了，记录一下
            if root.val == val1:
                self.foundP = True
            if root.val == val2:
                self.foundQ = True
            return root

        return left if left else right

# given parent for each node, but problem don’t give you root
# 这道题其实不是公共祖先的问题，而是单链表相交的问题

class Solution:
    # 施展链表双指针技巧
    def lowestCommonAncestor(self, p: 'Node', q: 'Node') -> 'Node':
        a, b = p, q
        while a != b:
            # a 走一步，如果走到根节点，转到 q 节点
            if a is None:
                a = q
            else:
                a = a.parent
            # b 走一步，如果走到根节点，转到 p 节点
            if b is None:
                b = p
            else:
                b = b.parent
        return a

# just more checking nodes
# 需要注意的是，这两道题的题目都明确告诉我们这些节点必定存在于二叉树中，如果没有这个前提条件，就需要修改代码了。

class Solution:
    def lowestCommonAncestor(self, root: 'TreeNode', nodes: 'List[TreeNode]') -> 'TreeNode':
        # 将列表转化成哈希集合，便于判断元素是否存在
        values = set()
        for node in nodes:
            values.add(node.val)

        return self.find(root, values)

    def find(self, root: 'TreeNode', values: 'set') -> 'TreeNode':
        if root is None:
            return None
        # 前序位置
        if root.val in values:
            return root

        left = self.find(root.left, values)
        right = self.find(root.right, values)
        # 后序位置，已经知道左右子树是否存在目标值
        if left is not None and right is not None:
            # 当前节点是 LCA 节点
            return root

        return left if left is not None else right

class Solution:
    def countTarget(self, scores: List[int], target: int) -> int:
        left = 0
        right = 0
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                right = mid - 1
            elif nums[mid] < target:
                left = mid + 1
            elif nums[mid] > target:
                right = mid - 1

        if left < 0 or left > len(nums):
            return 0
        if nums[left] != target:
            return 0
        lower = left

        left = 0
        right = 0
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            elif nums[mid] > target:
                right = mid - 1

        if right < 0 or right > len(nums):
            return 0
        if nums[right] != target:
            return 0
        return right - lower + 1
